CREATE POLICY lessons_course_visibility ON public.lessons AS RESTRICTIVE FOR SELECT TO public USING(EXISTS(SELECT 1 FROM public.courses c WHERE c.id=course_id));
CREATE POLICY author_course_write_guard ON public.courses AS RESTRICTIVE FOR UPDATE TO authenticated USING((public.current_profile_role()='professor' AND instructor_id=auth.uid() AND institution_id IS NULL) OR public.organization_permission(institution_id,'ies','conteudo',scope_id)) WITH CHECK((public.current_profile_role()='professor' AND instructor_id=auth.uid() AND institution_id IS NULL) OR public.organization_permission(institution_id,'ies','conteudo',scope_id));
CREATE OR REPLACE FUNCTION public.guard_content_inputs() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='module_assessments' THEN IF NEW.minimum_score<=0 OR NEW.minimum_score>100 OR jsonb_typeof(NEW.questions)<>'array' OR jsonb_array_length(NEW.questions)=0 THEN RAISE EXCEPTION 'Avaliação inválida'; END IF; ELSIF TG_TABLE_NAME='lessons' THEN IF NEW.duration_min<=0 OR NEW.duration_min>1440 OR (NEW.video_path IS NOT NULL AND NEW.video_path !~ '^https://') THEN RAISE EXCEPTION 'Duração ou endereço de vídeo inválido'; END IF; ELSIF TG_TABLE_NAME='course_modules' THEN IF NEW.hours<=0 OR jsonb_typeof(NEW.game)<>'array' THEN RAISE EXCEPTION 'Módulo inválido'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER assessment_input_validation BEFORE INSERT OR UPDATE ON public.module_assessments FOR EACH ROW EXECUTE FUNCTION public.guard_content_inputs();
CREATE TRIGGER lesson_input_validation BEFORE INSERT OR UPDATE ON public.lessons FOR EACH ROW EXECUTE FUNCTION public.guard_content_inputs();
CREATE TRIGGER module_input_validation BEFORE INSERT OR UPDATE ON public.course_modules FOR EACH ROW EXECUTE FUNCTION public.guard_content_inputs();
CREATE OR REPLACE FUNCTION public.guard_author_only_profiles() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user='authenticated' AND NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN RAISE EXCEPTION 'Transfira titularidade pelo fluxo autorizado'; END IF; RETURN NEW; END $$;
CREATE TRIGGER company_owner_guard BEFORE UPDATE ON public.companies FOR EACH ROW EXECUTE FUNCTION public.guard_author_only_profiles();
CREATE TRIGGER institution_owner_guard BEFORE UPDATE ON public.institutions FOR EACH ROW EXECUTE FUNCTION public.guard_author_only_profiles();
REVOKE EXECUTE ON FUNCTION public.handle_new_user(),public.set_learning_profile_role(),public.guard_profile_authority(),public.audit_organization_job(),public.guard_learning_evidence(),public.guard_course_publication(),public.guard_organization_reference(),public.guard_profile_namespace(),public.guard_content_inputs(),public.guard_author_only_profiles() FROM PUBLIC,anon,authenticated;